<template><div class="dash-stack"><div class="dash-toolbar"><div><h2>{{kind==='updates'?'Draft updates':'Draft creates'}}</h2><p>Work in progress is private to officers assigned to the same area.</p></div><IconButton v-if="kind==='creates'" icon="add" label="Create land draft" @click="create"/></div><div class="glass-panel"><div v-if="error" class="inline-alert">{{error}}</div><div v-if="loading" class="state-message">Loading drafts…</div><div v-else-if="!result.items?.length" class="state-message">No {{kind}} drafts.</div><div v-else class="table-scroll"><table class="glass-table"><thead><tr><th>Land / Draft</th><th>Last updated</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="d in result.items" :key="d.landId||d.id"><td><b>{{d.landId||d.id}}</b></td><td>{{new Date(d.updatedAt).toLocaleString()}}</td><td><span v-if="d.isStale" class="status-tag warn">Stale</span><span v-else class="status-tag">Draft</span></td><td class="actions"><IconButton icon="edit" label="Edit draft" @click="open(d)"/><IconButton icon="publish" label="Send to final record" @click="publish(d)"/><IconButton icon="delete" label="Delete draft" variant="danger" @click="remove(d)"/></td></tr></tbody></table></div><div class="pagination"><span>Page {{result.page||1}} of {{result.totalPages||0}}</span><div><IconButton icon="previous" label="Previous page" :disabled="!result.hasPrevious" @click="load((result.page||1)-1)"/><IconButton icon="next" label="Next page" :disabled="!result.hasNext" @click="load((result.page||1)+1)"/></div></div></div><ConfirmDialog :open="!!pendingAction" :title="pendingAction?.type==='publish'?'Publish land draft':'Delete land draft'" :message="pendingAction?.type==='publish'?'Send this draft to the final land record?':'Delete this draft? This cannot be undone.'" :confirm-label="pendingAction?.type==='publish'?'Send to final':'Delete draft'" :danger="pendingAction?.type==='delete'" @cancel="pendingAction=null" @confirm="confirmAction"/></div></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{platformApi}from'@/services/platform';import api from'@/services/api';import IconButton from'@/components/ui/IconButton.vue';import ConfirmDialog from'@/components/ui/ConfirmDialog.vue';const route=useRoute(),router=useRouter(),kind=String(route.params.kind||'updates'),result=ref<any>({items:[]}),loading=ref(false),pendingAction=ref<any>(null),error=ref('');async function load(page=1){loading.value=true;try{result.value=(await(kind==='updates'?platformApi.updateDrafts(page):platformApi.createDrafts(page))).data}finally{loading.value=false}}function open(d:any){router.push(kind==='updates'?`/dashboard/landofficer/drafts/updates/${d.landId}`:`/dashboard/landofficer/drafts/creates/${d.id}`)}function publish(d:any){pendingAction.value={type:'publish',draft:d}}function remove(d:any){pendingAction.value={type:'delete',draft:d}}async function confirmAction(){const action=pendingAction.value;if(!action)return;const d=action.draft,id=d.landId||d.id;try{if(action.type==='publish')await api.post(`/officer/drafts/${kind}/${id}/publish`,{});else await api.delete(`/officer/drafts/${kind}/${id}`);pendingAction.value=null;await load(result.value.page||1)}catch(e:any){error.value=e.response?.data?.detail||'Could not complete draft action'}}function create(){router.push('/dashboard/landofficer/drafts/creates/new')}onMounted(()=>load());</script>
